function searchItemCard(item, s) {
  const sel = s ? theme.reverse(' > ') : '   '
  const name = s ? bold(item.full_name) : dim(item.full_name)
  const desc = item.description || 'No description'
  return [
    `${sel}${name}`,
    `   ${desc}`,
    `   ⭐ ${item.stargazers_count} · ${item.language || 'N/A'}`,
    `   rolecraft install ${item.full_name}`,
  ]
}
